<?= $this->extend('layouts/staff') ?><?= $this->section('content') ?><?= view('components/page_header',['title'=>'Appointments','description'=>'Review parent requests and update appointment status.']) ?><?php if(session('message')): ?><p class="mb-4 rounded-lg bg-green-50 p-3 text-sm text-green-800"><?= esc(session('message')) ?></p><?php endif ?><?php if(session('error')): ?><p class="mb-4 rounded-lg bg-amber-50 p-3 text-sm text-amber-900"><?= esc(session('error')) ?></p><?php endif ?><div class="card overflow-hidden"><div class="overflow-x-auto"><table class="w-full min-w-[850px] text-left text-sm"><thead class="bg-gray-50 text-xs uppercase text-gray-500"><tr><?php foreach(['Child','Parent','Type','Preferred date','Time slot','Status','Notes','Actions'] as $h): ?><th class="p-3"><?= esc($h) ?></th><?php endforeach ?></tr></thead><tbody class="divide-y divide-gray-100"><?php foreach($rows as $row): ?><tr><td class="p-3"><a class="text-accent" href="<?= site_url('children/'.$row['child_id']) ?>"><?= esc($row['first_name'].' '.$row['last_name']) ?></a><span class="block text-xs text-gray-500"><?= esc($row['child_code']??'') ?></span></td><td class="p-3"><?= esc($row['parent_first'].' '.$row['parent_last']) ?></td><td class="p-3"><?= esc(ucwords(str_replace('_',' ',$row['type']))) ?></td><td class="p-3"><?= esc(format_date($row['preferred_date'])) ?></td><td class="p-3"><?= esc($row['time_slot']??'—') ?></td><td class="p-3"><?= view('components/badge',['label'=>ucfirst($row['status']),'tone'=>$row['status']==='approved'?'success':($row['status']==='requested'?'warning':'neutral')]) ?></td><td class="p-3"><?= esc($row['notes']??'—') ?></td><td class="p-3"><?php if($row['status']==='requested'): ?><div class="flex gap-2"><form method="post" action="<?= site_url('appointments/'.$row['id'].'/approve') ?>"><?= csrf_field() ?><button class="min-h-11 rounded-lg bg-brand-800 px-3 text-white">Approve</button></form><details><summary class="btn-muted cursor-pointer">Decline</summary><form method="post" action="<?= site_url('appointments/'.$row['id'].'/decline') ?>"><?= csrf_field() ?><label class="form-label" for="reason-<?= $row['id'] ?>">Reason</label><input class="form-control" id="reason-<?= $row['id'] ?>" name="reason" required><button class="mt-2 min-h-11 rounded bg-red-700 px-3 text-white">Confirm</button></form></details></div><?php elseif($row['status']==='approved'): ?><form method="post" action="<?= site_url('appointments/'.$row['id'].'/complete') ?>"><?= csrf_field() ?><button class="btn-muted">Mark complete</button></form><?php else: ?>—<?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="8" class="p-6 text-center text-gray-500">No appointment requests.</td></tr><?php endif ?></tbody></table></div></div><div class="mt-4"><?= $pager->links() ?></div><?= $this->endSection() ?>
